	(39, 3, 'Pescadores constructores', 'Egipcia', '{"mazoCards":{"20":2,"81":1,"84":2,"88":1,"91":1,"93":1,"96":2,"124":2,"127":2,"141":2,"162":1,"167":2,"175":1,"215":2,"233":1,"234":1,"242":1,"264":2,"266":2,"267":2,"269":2,"277":2,"289":2,"332":2,"355":2,"358":2,"437":2,"508":1,"619":2,"722":1,"735":2,"762":2,"763":2},"currentPantheon":"Egipcia","cardsDetails":[{"ID":"20","Nombre":"Karasu Tengu","Tipo":"Personaje","Mitologia":"Japonesa","Fuerza":"1","Poder":"5","Coste":"3","Texto - Habilidades":"INFLUENCIA: Elimina 1P de Karasu Tengu; elimina 1P de la reserva de su oponente.","Claves":"Demonio","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Japoneses\\/Karasu Tengu.png","count":2},{"ID":"81","Nombre":"Duat","Tipo":"Panteón","Mitologia":"Egipcia","Poder":"19","Texto - Habilidades":"INFLUENCIA: Elimina 2P; descarta todas las cartas de un oráculo de un jugador con igual o mayor número de oráculos que tu.","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Egipcios\\/Duat.png","count":1},{"ID":"84","Nombre":"Cleopatra","Tipo":"Personaje","Mitologia":"Egipcia","Fuerza":"0","Poder":"5","Coste":"3","Texto - Habilidades":"INFLUENCIA: Gana 1P en tu personaje.","Claves":"Reina","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Egipcios\\/Cleopatra.png","count":2},{"ID":"88","Nombre":"Isis","Tipo":"Personaje","Mitologia":"Egipcia","Fuerza":"3","Poder":"8","Coste":"6","Texto - Habilidades":"INFLUENCIA: Elimina 1P (de tu reserva); elimina 1P de las reservas contrarias.","Claves":"Dios · Invocadora","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Egipcios\\/Isis.png","count":1},{"ID":"91","Nombre":"Thot","Tipo":"Personaje","Mitologia":"Egipcia","Fuerza":"3","Poder":"7","Coste":"5","Texto - Habilidades":"INFLUENCIA: Elimina 1P de Thot; gana 2P en un recurso en tu oráculo.","Claves":"Dios · Alquimista · Constructor","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Egipcios\\/Thot.png","count":1},{"ID":"93","Nombre":"Bastet","Tipo":"Personaje","Mitologia":"Egipcia","Fuerza":"2","Poder":"7","Coste":"5","Texto - Habilidades":"INFLUENCIA: Elimina hasta 2P de un oráculo.","Claves":"Diosa","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Egipcios\\/Bastet.png","count":1},{"ID":"96","Nombre":"Imhotep","Tipo":"Personaje","Mitologia":"Egipcia","Fuerza":"1","Poder":"4","Coste":"3","Texto - Habilidades":"INFLUENCIA: Gana 1P en Imhotep por cada recurso en tu panteón, máximo 3.","Claves":"Invocador · Constructor","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Egipcios\\/Imhotep.png","count":2},{"ID":"124","Nombre":"Luces del norte","Tipo":"Evento","Texto - Habilidades":"Después de revelar tus oráculos gana 2P en tu personaje en un oráculo.","Claves":"Festival","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Eventos\\/Luces del norte.png","count":2},{"ID":"127","Nombre":"Hinamatsuri","Tipo":"Evento","Texto - Habilidades":"Gana 3P","Claves":"Festival","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Eventos\\/Hinamatsuri.png","count":2},{"ID":"141","Nombre":"Shemu","Tipo":"Evento","Texto - Habilidades":"Todos los jugadores eliminan 1P.","Claves":"Festival","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Eventos\\/Shemu.png","count":2},{"ID":"162","Nombre":"Westminster","Tipo":"Recurso","Coste":"2","Texto - Habilidades":"INFLUENCIA: Cansa Westminster; elimina 1P de un personaje en un panteón o un oráculo.","Claves":"Único · Punto de Poder","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Recursos\\/Westminster.png","count":1},{"ID":"167","Nombre":"Pescadores","Tipo":"Recurso","Coste":"2","Texto - Habilidades":"INFLUENCIA: Cansa Pescadores; elimina 1P de la reserva de un oponente.","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Recursos\\/Pescadores.png","count":2},{"ID":"175","Nombre":"Guiza","Tipo":"Recurso","Mitologia":"Egipcia","Coste":"3","Texto - Habilidades":"INFLUENCIA: Cansa Guiza; gana 1P por cada recurso que controles; máximo 3.","Claves":"Único · Egipto","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Recursos\\/Guiza.png","count":1},{"ID":"215","Nombre":"Origami","Tipo":"Equipo","Fuerza":"0","Poder":"0","Coste":"2","Texto - Habilidades":"INFLUENCIA: Cansa Origami; mueve 1P de la reserva de tu oponente a un personaje enmigo.","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Equipos\\/Origami.png","count":2},{"ID":"233","Nombre":"Talismán de aire","Tipo":"Equipo","Fuerza":"0","Poder":"1","Coste":"2","Texto - Habilidades":"Cuesta 1P menos para Takami-misubi. INFLUENCIA: Prepara un recurso de coste 2 o menos, puedes volver a usarlo este turno.","Claves":"Aire · Único","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Equipos\\/Talismán de aire.png","count":1},{"ID":"234","Nombre":"Talismán de agua","Tipo":"Equipo","Fuerza":"0","Poder":"1","Coste":"2","Texto - Habilidades":"Cuesta 1P menos para Ame-no-mi-Kurami. ENFRENTAMIENTO: Elimina 1P de éste personaje; puedes volver a poder jugar su habilidad.","Claves":"Agua · Único","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Equipos\\/Talismán de agua.png","count":1},{"ID":"242","Nombre":"Hapy","Tipo":"Equipo","Fuerza":"-1","Poder":"-1","Coste":"1","Texto - Habilidades":"Todas las transferencias se reducen en 1.","Claves":"Único","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Equipos\\/Hapy.png","count":1},{"ID":"264","Nombre":"La venganza de las Erinias","Tipo":"Acción","Coste":"1","Texto - Habilidades":"ENFRENTAMIENTO: Cada jugador que participe en este enfrentamiento elimina tanto poder como personajes tenga en su panteón","Claves":"Entorno","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Acciones\\/La venganza de las Erinias.png","count":2},{"ID":"266","Nombre":"La nave blanca","Tipo":"Acción","Coste":"0","Texto - Habilidades":"INFLUENCIA: Gana 1P por cada recurso en tu panteón (máximo 3). ","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Acciones\\/La nave blanca.png","count":2},{"ID":"267","Nombre":"Cabeza de Medusa","Tipo":"Acción","Coste":"2","Texto - Habilidades":"INFLUENCIA: Agota a un personaje enemigo.","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Acciones\\/Cabeza de Medusa.png","count":2},{"ID":"269","Nombre":"Expulsión","Tipo":"Acción","Coste":"1","Texto - Habilidades":"ENFRENTAMIENTO: Mueve a un personaje enemigo a su panteón.","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Acciones\\/Expulsion.png","count":2},{"ID":"277","Nombre":"Mitsudomoe","Tipo":"Acción","Coste":"1","Texto - Habilidades":"ENFRENTAMIENTO: Gana 2P en tu personaje y elimina 2P en un personaje enemigo.","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Acciones\\/Mitsudomoe.png","count":2},{"ID":"289","Nombre":"Nyar llama a su puerta","Tipo":"Acción","Coste":"0","Texto - Habilidades":"INFLUENCIA: Cambia la resolución de este enfrentamiento por: \\"el jugador que gane elimina una habilidad de un panteón\\". ","Claves":"Batalla","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Acciones\\/Nyar llama a su puerta.png","count":2},{"ID":"332","Nombre":"Mirada de Kefren","Tipo":"Acción","Coste":"1","Texto - Habilidades":"INFLUENCIA: Cansa y agota a tu mortal; elimina tanto poder como el elimado de una reserva contraria; máximo2.","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Acciones\\/Mirada de Kefren.png","count":2},{"ID":"355","Nombre":"Dátiles para los dioses","Tipo":"Acción","Coste":"1","Texto - Habilidades":"ENFRENTAMIENTO: Cansa tu dios; elimina 1P de la reserva de tu oponente.","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Acciones\\/Datiles para los dioses.png","count":2},{"ID":"358","Nombre":"El acertijo de la esfinge","Tipo":"Acción","Coste":"0","Texto - Habilidades":"INFLUENCIA: Elimina 1P de un personaje en un oráculo.","Era":"Era I","URL-IMG":"GDM\\/Era I\\/Acciones\\/El acertijo de la esfinge.png","count":2},{"ID":"437","Nombre":"Amenhotep III","Tipo":"Personaje","Mitologia":"Egipcia","Fuerza":"2","Poder":"6","Coste":"4","Texto - Habilidades":"ENFRENTAMIENTO: Prepara un recurso de coste 2 o menos, puedes volver a usarlo este turno.","Claves":"Faraón · Constructor","Era":"Era II","URL-IMG":"GDM\\/Era II\\/Egipcios\\/Amenhotep III.png","count":2},{"ID":"508","Nombre":"Muork","Tipo":"Personaje","Mitologia":"Neutral","Fuerza":"0","Poder":"2","Coste":"1","Texto - Habilidades":"INFLUENCIA: Copia la habilidad de un recurso de coste 2 o menos.","Claves":"Senador · Único","Era":"Era II","URL-IMG":"GDM\\/Era II\\/Neutrales\\/Muork.png","count":1},{"ID":"619","Nombre":"Twynpath","Tipo":"Recurso","Coste":"1","Texto - Habilidades":"INFLUENCIA: Cansa Twynpath; cambia las habilidades de un recurso de INFLUENCIA A ENFRENTAMIENTO.","Era":"Era II","URL-IMG":"GDM\\/Era II\\/Recursos\\/Twynpath.png","count":2},{"ID":"722","Nombre":"Maldición de Izanami","Tipo":"Acción","Coste":"1","Texto - Habilidades":"El jugador que use la habilidad de su panteón elimina 1P de su reserva. INFLUENCIA: Pon esta carta en juego permanente en tu panteón.","Claves":"Portal · Único","Era":"Era II","URL-IMG":"GDM\\/Era II\\/Acciones\\/Maldición de Izanami.png","count":1},{"ID":"735","Nombre":"El engaño de Lilith","Tipo":"Acción","Coste":"0","Texto - Habilidades":"INFLUENCIA: Cambia permanentemente la habilidad de un recurso de INFLUENCIA a ENFRENTAMIENTO.","Era":"Era II","URL-IMG":"GDM\\/Era II\\/Acciones\\/El engaño de Lilith.png","count":2},{"ID":"762","Nombre":"Inspección de Kufuan","Tipo":"Acción","Coste":"0","Texto - Habilidades":"INFLUENCIA: Cansa tu constructor; prepara tu recurso de coste 2 o menos y puedes volver a usarlo.","Era":"Era II","URL-IMG":"GDM\\/Era II\\/Acciones\\/Inspección de Kufuan.png","count":2},{"ID":"763","Nombre":"Addanc","Tipo":"Acción","Coste":"1","Texto - Habilidades":"ENFRENTAMIENTO: Elimina 1P de la reserva de un enemigo; gana 1P en tu oráculo revelado.","Era":"Era II","URL-IMG":"GDM\\/Era II\\/Acciones\\/Addanc.png","count":2}]}', '2026-05-02 12:13:24', '2026-05-02 12:13:24');
